local UIModule = CS.Engine.UI.UIModule
local GameObject = CS.UnityEngine.GameObject
local KCookie = CS.Engine.Lib.KCookie
local kTool = CS.Engine.Lib.KTool
--local Yielders = CS.Engine.Lib.Yielders
local Image = CS.UnityEngine.UI.Image
local Animator = CS.UnityEngine.Animator
local URPCameraController = CS.Game.Native.URP.URPCameraController
local cs_coroutine = require('XLua.cs_coroutine')

---@type CriWareUtils
local CriWareUtils = import('Game.Entry.CriWareUtilsFix')

local CompletionAnimation = "Completion"
local GoAnimation = "Go"
local EntryAnimation = "Loading"
local EntryAnimationIndex = Animator.StringToHash(EntryAnimation)

local PlayerPrefsUtility = CS.Engine.Tools.PlayerPrefsUtility
local Application = CS.UnityEngine.Application
local AppEngine = CS.Engine.Lib.AppEngine
local SmallPackageDownloaded = "SmallPackageDownloaded"

---IsSmallPackage
---判断是否为小包的逻辑
local function IsSmallPackage()
    local isSmallPackage = checkNumber(AppEngine.GetConfig("Engine", "IsSmallPackage", false))
    local preVersion = PlayerPrefsUtility.GetEncryptedString(SmallPackageDownloaded, "")
    local isSmall = false
    if isSmallPackage == 1 and preVersion ~= Application.version then
        ---最新的分包的逻辑，要进行检测更新相关的逻辑
        isSmall = true
    end
    return isSmall
end

---@class LoginLoadingPanel
---@field ProgressText                    TMPro.TextMeshProUGUI
---@field LoadingSlider                    UnityEngine.UI.Image
---@field Root                    UnityEngine.RectTransform
local LoginLoadingPanel = Class('LoginLoadingPanel')

function LoginLoadingPanel:__init()
    self.co = nil
    self.loadingType = Constants.LoadingType.Battle
    self.args = nil
    self.dialogArgs = nil
    self._reqPro = -1
    -- self._loader = nil
    ---@type UnityEngine.Animator
    self._animator = nil
end

function LoginLoadingPanel:__delete()
    self.co = nil
    self.loadingType = nil
    self.args = nil
    self.dialogArgs = nil
    -- self._loader = nil
    self._reqPro = nil
    self._animator = nil
end

function LoginLoadingPanel:SetArg(args, dialogs, loadingType, enableResume)
    self.args = args
    self.dialogArgs = dialogs
    self.loadingType = checkInt(loadingType)
    -- self._loader = loader
    ---@type UnityEngine.UI.Image
    self.LoadingSlider = kTool.GetComponent(self.LoadingSlider.gameObject, typeof(Image))
    ---@type UnityEngine.Animator
    self._animator = kTool.GetComponent(self.Root.gameObject, typeof(Animator))
    self._animator.speed = 0
    if args then
        CriWareUtils.PlayRandomBGMFromCDList()
    end
    local title = self.Root.transform:Find("BgContainer/Title")
    if title then
        kTool.SetActive(title, false)
    end
end

function LoginLoadingPanel:Start()
    if not isNull(self.co) then
        cs_coroutine.stop(self.co)
        self.co = nil
    end
    xTry(function()
        if not IsSmallPackage() then
            ---每次进入的loading开始时准备goodNode缓存池
            CS.Engine.Lib.GOPoolManager.Instance:PreparePool("Prefabs/Common/GoodNode.prefab", 12)
        end
    end)
    self.co = cs_coroutine.start(function()
        CS.UnityEngine.Application.backgroundLoadingPriority = CS.UnityEngine.ThreadPriority.High
        cs_coroutine.yield_return(CoYield(0.15))
        local title = self.Root.transform:Find("BgContainer/Title")
        if title then
            kTool.SetActive(title, true)
        end
        if not isNull(self._animator) then
            cs_coroutine.yield_return(self._animator:WaitUntilAniCompleted())
            self._animator:Play(EntryAnimationIndex, -1, 0);
            self:__Progress(0)
            if not isNull(UIModule.RootCanvas.transform:Find("UINavigationBarRoot")) then
                GameUtils.HideBlack(0.3)   -- 序章4剧情结束之后，要请求服务器，等服务器返回以后才进入主界面。剧情结束以后会ShowBlack，然后这里进入loading的时候要HideBlack
            end
        end
        URPCameraController.Instance:SetMainCameraActive(true)
        if self.args then
            cs_coroutine.yield_return(UIModule.OpenScreen(self.args, true, self.dialogArgs))
            ---@type XMainHome
            local env = UIModule.CurrentScreen.Env
            env:SetLoadingUI(self)
            cs_coroutine.yield_return(env:AsyncLoadingResources())
        end
    end)
end

function LoginLoadingPanel:PlayAndWaitFinish()
    if not isNull(self._animator) then
        self._animator.speed = 1
        cs_coroutine.yield_return(self._animator:PlayAndWait(Animator.StringToHash(CompletionAnimation)))
    end
end

function LoginLoadingPanel:__Progress(value)
    value = math.min(value, 1)
    local progress = math.floor(checkNumber(value * 100))
    local _string = string.format("%0.1f", progress)
    self.ProgressText.text = string.format("%s<size=24>%%</size>", _string)
    self.LoadingSlider.fillAmount = value
    self._animator:Play(EntryAnimationIndex, -1, value)
end

function LoginLoadingPanel:Close()
    KCookie.Set("isFirst", false)
    if not isNull(self.co) then
        cs_coroutine.stop(self.co)
        self.co = nil
    end
    CS.UnityEngine.Application.backgroundLoadingPriority = CS.UnityEngine.ThreadPriority.BelowNormal
    GameObject.Destroy(self.controller.gameObject, 0.1)
end

function LoginLoadingPanel:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return LoginLoadingPanel